import{_ as t,o as n,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"02 — Authentication & Profile","description":"","frontmatter":{},"headers":[],"relativePath":"ba/02-authentication-profile.md","filePath":"ba/02-authentication-profile.md"}'),o={name:"ba/02-authentication-profile.md"};function l(h,i,r,c,g,s){return n(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="_02-—-authentication-profile" tabindex="-1">02 — Authentication &amp; Profile <a class="header-anchor" href="#_02-—-authentication-profile" aria-label="Permalink to &quot;02 — Authentication &amp; Profile&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="_1-authentication-fr-3-2" tabindex="-1">1. Authentication (FR 3.2) <a class="header-anchor" href="#_1-authentication-fr-3-2" aria-label="Permalink to &quot;1. Authentication (FR 3.2)&quot;">​</a></h2><h3 id="_3-2-1-—-sign-up" tabindex="-1">3.2.1 — Sign Up <a class="header-anchor" href="#_3-2-1-—-sign-up" aria-label="Permalink to &quot;3.2.1 — Sign Up&quot;">​</a></h3><ul><li>Đăng ký bằng email, <strong>verify OTP</strong> để xác thực email là thật.</li><li><strong>Check lỗi viết hoa chữ đầu email</strong>: <code>User@gmail.com</code> và <code>user@gmail.com</code> phải được nhận diện là <strong>cùng 1 tài khoản</strong> — không tạo account trùng do khác hoa/thường ở phần local-part email.</li><li>Role: GUEST (chưa đăng nhập thực hiện được).</li></ul><h3 id="_3-2-2-—-sign-in-with-email" tabindex="-1">3.2.2 — Sign In With Email <a class="header-anchor" href="#_3-2-2-—-sign-in-with-email" aria-label="Permalink to &quot;3.2.2 — Sign In With Email&quot;">​</a></h3><ul><li>Đăng nhập bằng email/password, <strong>không cần gửi OTP lại</strong> (khác với Sign Up).</li><li>Role: GUEST.</li></ul><h3 id="_3-2-3-—-sign-in-with-google-oauth" tabindex="-1">3.2.3 — Sign In with Google OAuth <a class="header-anchor" href="#_3-2-3-—-sign-in-with-google-oauth" aria-label="Permalink to &quot;3.2.3 — Sign In with Google OAuth&quot;">​</a></h3><ul><li><strong>Ghi chú hiện trạng</strong>: login hiện tại theo báo cáo <strong>vẫn chưa chạy được</strong> — cần coi lại toàn bộ flow (không chỉ là feature mới, là bug fix trên flow cũ).</li><li>Role: GUEST.</li></ul><h3 id="_3-2-4-—-reset-password" tabindex="-1">3.2.4 — Reset Password <a class="header-anchor" href="#_3-2-4-—-reset-password" aria-label="Permalink to &quot;3.2.4 — Reset Password&quot;">​</a></h3><ul><li>Khi user quên mật khẩu: hệ thống gửi <strong>link đổi mật khẩu HOẶC mã OTP</strong> đến email để xác nhận trước khi cho đổi mật khẩu mới.</li><li>Role: USER.</li></ul><h3 id="_3-2-5-—-change-password" tabindex="-1">3.2.5 — Change Password <a class="header-anchor" href="#_3-2-5-—-change-password" aria-label="Permalink to &quot;3.2.5 — Change Password&quot;">​</a></h3><ul><li>Đổi mật khẩu khi đã đăng nhập.</li><li><strong>Bắt buộc có bước confirm lại</strong> trước khi áp dụng đổi mật khẩu (ví dụ nhập lại mật khẩu mới 2 lần, hoặc confirm modal).</li><li>Role: USER.</li></ul><h3 id="_3-2-6-—-otp-verification" tabindex="-1">3.2.6 — OTP Verification <a class="header-anchor" href="#_3-2-6-—-otp-verification" aria-label="Permalink to &quot;3.2.6 — OTP Verification&quot;">​</a></h3><ul><li>Màn hình chuyên dụng để user điền mã OTP (dùng chung cho Sign Up, Reset Password, 2FA).</li><li>Role: USER.</li></ul><h3 id="_3-2-7-—-two-factor-authentication-2fa-totp" tabindex="-1">3.2.7 — Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#_3-2-7-—-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;3.2.7 — Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h3><ul><li>Hiện trạng: đang có 2 cách xác thực song song — scan QR để add vào app Authenticator, VÀ nhập mã OTP.</li><li><strong>Thay đổi</strong>: bỏ tính năng copy secret key và bỏ backup codes — chỉ giữ scan QR + nhập OTP, đơn giản hóa để giảm bề mặt tấn công và giảm phức tạp UI.</li><li>Role: USER.</li></ul><h3 id="_3-2-8-—-sign-out" tabindex="-1">3.2.8 — Sign Out <a class="header-anchor" href="#_3-2-8-—-sign-out" aria-label="Permalink to &quot;3.2.8 — Sign Out&quot;">​</a></h3><ul><li>Đăng xuất, nhưng <strong>phải lưu lại thông tin &quot;last used platform&quot;</strong> (nền tảng đăng nhập lần cuối) để user đăng nhập lại tiện hơn (ví dụ nhớ đã dùng Google OAuth lần trước, gợi ý nút đó nổi bật hơn khi quay lại).</li><li>Role: USER.</li></ul><h3 id="_3-2-9-—-deactivate-account" tabindex="-1">3.2.9 — Deactivate Account <a class="header-anchor" href="#_3-2-9-—-deactivate-account" aria-label="Permalink to &quot;3.2.9 — Deactivate Account&quot;">​</a></h3><ul><li><strong>Soft delete</strong> tài khoản — không xóa cứng dữ liệu.</li><li>Role: USER.</li></ul><h2 id="_2-profile-fr-3-3" tabindex="-1">2. Profile (FR 3.3) <a class="header-anchor" href="#_2-profile-fr-3-3" aria-label="Permalink to &quot;2. Profile (FR 3.3)&quot;">​</a></h2><h3 id="_3-3-1-—-view-user-profile" tabindex="-1">3.3.1 — View User Profile <a class="header-anchor" href="#_3-3-1-—-view-user-profile" aria-label="Permalink to &quot;3.3.1 — View User Profile&quot;">​</a></h3><ul><li><strong>[CONFIRMED 2026-09-17]</strong> Field chuẩn cho User Profile — thiết kế theo nhu cầu thực tế của người làm truyền thông (Agency member): <ul><li>Họ tên đầy đủ (<code>fullName</code>)</li><li>Avatar (<code>avatarUrl</code>)</li><li>Email (<code>email</code>) — cố định, không sửa được ở đây (đổi email là flow riêng, nếu có)</li><li>Số điện thoại (<code>phone</code>)</li><li>Chức danh/vai trò chuyên môn (<code>professionalTitle</code> — ví dụ: Content Creator, Photographer, Account Manager — khác với <code>role</code> hệ thống ở Workspace, đây chỉ là label mô tả nghề nghiệp)</li><li>Bio ngắn (<code>bio</code>)</li><li>Portfolio/link mẫu việc đã làm (<code>portfolioUrl</code>, có thể nhiều link)</li><li>Ngôn ngữ làm việc (<code>workingLanguage</code>)</li><li>Timezone cá nhân (<code>timezone</code> — khác với Timezone Configuration của Workspace ở FR 3.4.13, đây là timezone hiển thị UI cho riêng user)</li><li>Ngày tham gia hệ thống (<code>joinedAt</code>)</li></ul></li><li>Role: USER.</li></ul><h3 id="_3-3-2-—-update-user-profile" tabindex="-1">3.3.2 — Update User Profile <a class="header-anchor" href="#_3-3-2-—-update-user-profile" aria-label="Permalink to &quot;3.3.2 — Update User Profile&quot;">​</a></h3><ul><li>Đổi tên FR: <strong>gộp thành 1 FR duy nhất là &quot;Update Profile&quot;</strong> (không tách View riêng khỏi Update ở tầng đặt tên FR, theo ghi chú gốc &quot;Chuyển thành 1 FR là Update Profile&quot;).</li><li>Role: USER.</li></ul><h3 id="_3-3-3-—-view-client-profile" tabindex="-1">3.3.3 — View Client Profile <a class="header-anchor" href="#_3-3-3-—-view-client-profile" aria-label="Permalink to &quot;3.3.3 — View Client Profile&quot;">​</a></h3><ul><li>Khi 1 User đóng vai trò <strong>Client</strong> tham gia vào Workspace của Agency khác (không phải Agency của chính họ), hệ thống có 1 <strong>Client Profile riêng biệt</strong> với User Profile thông thường.</li><li>Mục đích: khi Client đó tham gia workspace của Agency khác (dự án khác), <strong>không cần cập nhật lại thông tin từ đầu</strong> — chỉ cần dùng lại Client Profile đã có.</li><li>Đây chính là cơ chế hỗ trợ &quot;Client là actor ngoài, tái sử dụng profile xuyên Agency/Workspace&quot; đã nêu ở <a href="./01-organization-structure.html">01-organization-structure.md</a> mục 5.</li><li><strong>[CONFIRMED 2026-09-17]</strong> <code>ClientProfile</code> là <strong>bảng tách riêng hoàn toàn khỏi <code>User</code></strong> (không dùng chung bảng User + thêm cột) — vì <strong>1 User có thể có nhiều Client Profile khác nhau</strong> (ví dụ: cùng 1 người vừa là Client của Agency A với thông tin công ty X, vừa là Client của Agency B với thông tin công ty Y — 2 profile độc lập, không gộp chung). Xem chi tiết field ở <a href="./11-data-entities-glossary.html">11-data-entities-glossary.md</a>.</li><li>Role: USER (với vai trò Client).</li></ul><h3 id="_3-3-4-—-update-client-profile" tabindex="-1">3.3.4 — Update Client Profile <a class="header-anchor" href="#_3-3-4-—-update-client-profile" aria-label="Permalink to &quot;3.3.4 — Update Client Profile&quot;">​</a></h3><ul><li>Cập nhật Client Profile, nhưng <strong>KHÔNG được update email</strong> — email Client cố định, có thể vì email là khóa liên kết định danh Client xuyên các Agency khác nhau, đổi sẽ phá vỡ liên kết đó.</li><li>Role: USER (với vai trò Client).</li></ul>',30)])])}const p=t(o,[["render",l]]);export{d as __pageData,p as default};
